In this section, I’ll learn how to create interactive information dashboard by using reactable and reactablefmtr packages. Before getting started, it is highly recommended to visit the webpage of these two packages and review all the materials provided on the webpages at least once. I don’t have to understand and remember everything provided but at least have an overview of the purposes and functions provided by them.


I’ll start by preparing my data in a suitable format for reactable:

# Convert to a wide format for reactable display
report_wide &lt;- report %&gt;%
  pivot_wider(names_from = Month, values_from = Sales)

# Create a basic interactive table
reactable(
  report_wide,
  defaultPageSize = 13,
  filterable = TRUE,
  searchable = TRUE,
  striped = TRUE,
  highlight = TRUE
)









# Summary statistics table
sales_summary &lt;- report %&gt;% 
  group_by(Product) %&gt;% 
  summarise("Min" = min(Sales, na.rm = TRUE),
            "Max" = max(Sales, na.rm = TRUE),
            "Average" = mean(Sales, na.rm = TRUE),
            "Total" = sum(Sales, na.rm = TRUE))

# Display with reactable
reactable(
  sales_summary,
  defaultPageSize = 13,
  columns = list(
    Min = colDef(format = colFormat(prefix = "$", separators = TRUE, digits = 0)),
    Max = colDef(format = colFormat(prefix = "$", separators = TRUE, digits = 0)),
    Average = colDef(format = colFormat(prefix = "$", separators = TRUE, digits = 2)),
    Total = colDef(format = colFormat(prefix = "$", separators = TRUE, digits = 0))
  )
)









# Add conditional formatting to highlight high and low values
reactable(
  sales_summary,
  defaultPageSize = 13,
  columns = list(
    Min = colDef(
      format = colFormat(prefix = "$", separators = TRUE, digits = 0),
      style = function(value) {
        list(color = if (value &lt; median(sales_summary$Min)) "red" else "black")
      }
    ),
    Max = colDef(
      format = colFormat(prefix = "$", separators = TRUE, digits = 0),
      style = function(value) {
        list(color = if (value &gt; median(sales_summary$Max)) "blue" else "black")
      }
    ),
    Average = colDef(
      format = colFormat(prefix = "$", separators = TRUE, digits = 2)
    ),
    Total = colDef(
      format = colFormat(prefix = "$", separators = TRUE, digits = 0),
      style = function(value) {
        list(fontWeight = if (value &gt; median(sales_summary$Total)) "bold" else "normal")
      }
    )
  )
)









# Combine with performance data
performance_data &lt;- left_join(
  sales_summary,
  bullet[, c("Product", "Target", "Actual")]
)

# Calculate performance metrics
performance_data &lt;- performance_data %&gt;%
  mutate(
    Performance = Actual / Target * 100,
    Status = case_when(
      Performance &gt;= 100 ~ "Above Target",
      Performance &gt;= 90 ~ "Near Target",
      TRUE ~ "Below Target"
    )
  )

# Display with reactable
reactable(
  performance_data,
  defaultPageSize = 13,
  columns = list(
    Status = colDef(
      style = function(value) {
        if (value == "Above Target") {
          list(color = "green")
        } else if (value == "Near Target") {
          list(color = "orange")
        } else {
          list(color = "red")
        }
      }
    ),
    Performance = colDef(
      format = colFormat(suffix = "%", digits = 1)
    )
  )
)
